from copying import clone
def merge(defaults, overrides):
    result=clone(defaults)
    for key, override in overrides.items():
        if isinstance(override, dict) and key in result and isinstance(result[key], dict):
            result[key] = merge(result[key], override)
        elif override is not None:
            result[key] = override
    return result
